<div class="module-intro"><div><span class="eyebrow">GESTÃO DE DEMANDAS</span><h2>Ordens de serviço</h2><p>Abertura, aprovação, execução e encerramento.</p></div><?php if($canCreate): ?><button class="btn primary" data-toggle-target="order-form">＋ Nova O.S.</button><?php endif; ?></div>
<form method="get" class="filter-bar"><input name="q" placeholder="Número, descrição ou local" value="<?= e($filters['q']) ?>"><select name="status"><option value="">Todos os status</option><?php foreach(['Solicitada','Em análise','Aprovada','Em andamento','Pendente','Concluída','Cancelada'] as $s): ?><option <?= $filters['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><select name="priority"><option value="">Todas prioridades</option><?php foreach(['Baixa','Média','Alta','Urgente'] as $p): ?><option <?= $filters['priority']===$p?'selected':'' ?>><?= e($p) ?></option><?php endforeach; ?></select><button class="btn subtle">Filtrar</button></form>
<?php if($canCreate): ?><form id="order-form" class="panel form-panel hidden" method="post" action="<?= e($baseUrl) ?>/ordens/salvar"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><div class="section-heading"><div><h3>Abertura de ordem de serviço</h3><p>Numeração sequencial gerada no banco de dados.</p></div></div><div class="form-grid"><label>Solicitante *<input name="requester" required></label><label>Setor solicitante<input name="requesting_department"></label><label>Tipo de serviço *<input name="service_type" required></label><label>Prioridade<select name="priority"><option>Baixa</option><option>Média</option><option>Alta</option><option>Urgente</option></select></label><label>Local de execução *<input name="location" required></label><label>Prazo previsto<input type="datetime-local" name="due_at"></label><label>Responsável<select name="responsible_id"><option value="">A definir</option><?php foreach($staff as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></label><label class="full">Descrição da solicitação *<textarea name="description" rows="3" required></textarea></label></div><div class="form-actions"><button class="btn primary">Criar O.S.</button><button type="button" class="btn subtle" data-toggle-target="order-form">Cancelar</button></div></form><?php endif; ?>
<section class="panel"><div class="section-heading"><div><h3>Ordens cadastradas</h3><p><?= count($orders) ?> resultados</p></div></div><?php if(!$orders): ?><div class="table-empty">Nenhuma ordem encontrada.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Número</th><th>Abertura</th><th>Serviço</th><th>Solicitante</th><th>Prioridade</th><th>Status</th><th>Responsável</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><b>O.S. - <?= str_pad((string)$o['order_number'],4,'0',STR_PAD_LEFT) ?></b></td><td><?= date('d/m/Y H:i',strtotime($o['opened_at'])) ?></td><td><?= e($o['service_type']) ?><small><?= e($o['location']) ?></small></td><td><?= e($o['requester']) ?></td><td><span class="priority <?= strtolower($o['priority']) ?>"><?= e($o['priority']) ?></span></td><td><span class="state-pill"><?= e($o['status']) ?></span></td><td><?= e($o['responsible_name']??'A definir') ?></td><td><a class="text-link" href="<?= e($baseUrl) ?>/ordens/<?= (int)$o['id'] ?>">Abrir →</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>